def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
    - Multiplos de 3 son 'Fizz'
    - Multiplos de 5 son 'Buzz'
    - Multiplos de 15 son 'FizzBuzz'
    - El resto es el número como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales.
    Devuelve la tupla (elemento, longitud). Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_element = lista[0]
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_racha += 1
        else:
            if current_racha > max_racha:
                max_racha = current_racha
                max_element = lista[i - 1]
            current_racha = 1

    # Verificar la última racha
    if current_racha > max_racha:
        max_racha = current_racha
        max_element = lista[-1]

    return (max_element, max_racha)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    primos = []
    for i in range(2, n + 1):
        es_primo = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                es_primo = False
                break
        if es_primo:
            primos.append(i)
    return primos

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Un texto vacío está balanceado.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados, False en caso contrario.
    """
    if not s:
        return True

    open_brackets = {'(', '[', '{'}
    close_brackets = {')', ']', '}'}
    stack = []

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top = stack.pop()
            if top != char:
                return False

    return len(stack) == 0

def suma_digitos(n: int) -> int:
    """Suma los dígitos de un número y repite el proceso hasta quedarse con un solo dígito."""
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n


