def transpuesta(m):
    if not m:
        return []
    rows = len(m)
    cols = len(m[0])
    return [[m[i][j] for i in range(rows)] for j in range(cols)]

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del string están bien balanceados y anidados.
    Los demás caracteres se ignoran.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados, False en caso contrario.
    """
    open_paren = 0
    open_bracket = 0
    open_brace = 0

    for char in s:
        if char == '(':
            open_paren += 1
        elif char == '[':
            open_bracket += 1
        elif char == '{':
            open_brace += 1
        elif char == ')':
            if open_paren == 0:
                return False
            open_paren -= 1
        elif char == ']':
            if open_bracket == 0:
                return False
            open_bracket -= 1
        elif char == '}':
            if open_brace == 0:
                return False
            open_brace -= 1

    return open_paren == 0 and open_bracket == 0 and open_brace == 0

def anidar(plano: dict) -> dict:
    """
    Convierte un diccionario de claves con puntos en un diccionario anidado.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Un diccionario donde las claves son strings con puntos '.' separadores.

    Returns:
        Un diccionario anidado donde cada clave con puntos se descompone en una
        cadena de claves.
    """
    result = {}
    for key, value in plano.items():
        if '.' in key:
            parts = key.split('.')
            current = result
            for part in parts[:-1]:
                current = current.setdefault(part, {})
            current[parts[-1]] = value
        else:
            result[key] = value
    return result


# Ejemplo de uso:
if __name__ == "__main__":
    plano = {'a.b': 1, 'c.d.e': 2, 'f': 3}
    print(anidar(plano))
    # Salida: {'a': {'b': 1}, 'c': {'d': {'e': 2}}, 'f': 3}

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

def sumar_romanos(a: str, b: str) -> str:
    """
    Suma dos números romanos y devuelve el resultado en romano.

    Args:
        a: Primer número en formato romano.
        b: Segundo número en formato romano.

    Returns:
        El resultado de la suma en formato romano.
    """
    def valor_romano(s: str) -> int:
        valores = {
            "I": 1, "V": 5, "X": 10, "L": 50,
            "C": 100, "D": 500, "M": 1000
        }
        total = 0
        for i in range(len(s) - 1, -1, -1):
            total += valores[s[i]]
            if i > 0 and valores[s[i]] < valores[s[i - 1]]:
                total -= valores[s[i]]
        return total

    def romano_de_numero(n: int) -> str:
        if n == 0:
            return "0"
        if n < 10:
            return str(n)
        if n < 40:
            return "X" + romano_de_numero(n - 10)
        if n < 50:
            return "L" + romano_de_numero(n - 50)
        if n < 60:
            return "C" + romano_de_numero(n - 60)
        if n < 70:
            return "D" + romano_de_numero(n - 70)
        if n < 80:
            return "M" + romano_de_numero(n - 80)
        if n < 90:
            return "CM" + romano_de_numero(n - 900)
        if n < 100:
            return "XC" + romano_de_numero(n - 1000)
        if n < 1000:
            return "M" + romano_de_numero(n - 1000)
        if n < 10000:
            return "M" + romano_de_numero(n // 1000) + romano_de_numero(n % 1000)
        return str(n)

    a_val = valor_romano(a)
    b_val = valor_romano(b)
    resultado = a_val + b_val
    return romano_de_numero(resultado)


